// Compiles the contract and writes its ABI + bytecode into the website
// (attendance-app/contract.js), so the website can create classes by itself.
const fs = require("fs");
const path = require("path");
const hre = require("hardhat");

async function main() {
  await hre.run("compile");
  const { abi, bytecode } = await hre.artifacts.readArtifact("ClassAttendance");
  const out = path.join(__dirname, "..", "..", "attendance-app", "contract.js");
  const js =
    "// Generated by for-developers/scripts/build.js - do not edit by hand.\n" +
    "// The compiled ClassAttendance contract. The website deploys it when a teacher creates a class.\n" +
    `window.CLASS_CONTRACT = ${JSON.stringify({ abi, bytecode })};\n`;
  fs.writeFileSync(out, js);
  console.log(`Wrote ${path.relative(process.cwd(), out)} (${(js.length / 1024).toFixed(1)} KB)`);
}

main().catch((error) => {
  console.error(error);
  process.exitCode = 1;
});
